-- Courier tracking (docs/plans/cart-checkout.md §3 "Phase K migrations", §15 Phase K, K3):
-- shipment_events (courier history entries, de-duplicated on shipment + time + status so webhook
-- replays and repeated polls never add a row twice), shipping_webhook_events (the raw courier
-- webhook log, 12 months), and two bookkeeping columns on shipments: refetch_requested_at (a webhook
-- arrived while its re-fetch was debounced or failed; the poller reads the shipment next) and
-- stale_flagged_at (tracking_stale raised once per quiet spell).
-- Generated by drizzle-kit, then read. Hand edits: this header and the lock_timeout line.
--
-- Backward compatibility with the previous release (K2; CLAUDE.md expand/contract): additive. Two
-- new tables nothing released reads or writes, and two nullable columns without a default on
-- shipments that the K2 image never names (it selects whole rows through drizzle, which lists only
-- the columns it knows, and its inserts leave them NULL).
--
-- Locks: ADD COLUMN without a default is metadata-only (a brief ACCESS EXCLUSIVE on shipments, a
-- small table); the two foreign keys take SHARE ROW EXCLUSIVE on shipments and validate against
-- empty tables. lock_timeout makes the migration fail fast (and roll back entirely) instead of
-- queueing booking reads behind a long-running transaction.
SET LOCAL lock_timeout = '5s';--> statement-breakpoint
CREATE TABLE "shipment_events" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"shipment_id" uuid NOT NULL,
	"occurred_at" timestamp with time zone NOT NULL,
	"provider_status" text NOT NULL,
	"normalized_status" text,
	"description" text DEFAULT '' NOT NULL,
	"location" text,
	"source" text NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "shipment_events_shipment_id_occurred_at_provider_status_key" UNIQUE("shipment_id","occurred_at","provider_status"),
	CONSTRAINT "shipment_events_normalized_status_check" CHECK ("shipment_events"."normalized_status" is null or "shipment_events"."normalized_status" in ('pickup_requested', 'picked_up', 'in_transit', 'delivered', 'cancelled', 'returning', 'returned', 'problem')),
	CONSTRAINT "shipment_events_source_check" CHECK ("shipment_events"."source" in ('webhook', 'poll', 'staff'))
);
--> statement-breakpoint
CREATE TABLE "shipping_webhook_events" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"received_at" timestamp with time zone DEFAULT now() NOT NULL,
	"event" text,
	"provider_order_id" text,
	"shipment_id" uuid,
	"payload" jsonb,
	"raw_text" text,
	"body_bytes" integer NOT NULL,
	"processed_at" timestamp with time zone,
	"result" text,
	CONSTRAINT "shipping_webhook_events_payload_or_text_check" CHECK ("shipping_webhook_events"."payload" is null or "shipping_webhook_events"."raw_text" is null),
	CONSTRAINT "shipping_webhook_events_body_bytes_check" CHECK ("shipping_webhook_events"."body_bytes" >= 0)
);
--> statement-breakpoint
